/** Preview 折叠回归；在 ego-browser 的本地夹具页面运行，不访问真实任务或剪贴板。 */
import assert from 'node:assert/strict';
import { mkdir, writeFile } from 'node:fs/promises';

export async function runCollapseAcceptance(page, artifactDir) {
  const checks = [];
  const check = (name, condition) => { assert.ok(condition, name); checks.push(name); };
  const settle = () => page.evaluate(() => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve))));
  const select = async id => { await page.selectOption('[aria-label="Fixture"]', id); await settle(); };
  const toggle = async part => { await page.click(`[data-reader-part="${part}"] > .cx-reader-block-head .cx-reader-collapse`); await settle(); };
  const expanded = part => page.evaluate(part => document.querySelector(`[data-reader-part="${part}"] > .cx-reader-block-head .cx-reader-collapse`)?.getAttribute('aria-expanded') === 'true', part);
  const refresh = async () => { await page.evaluate(() => window.readerFixture.refresh()); await settle(); };
  const copy = async part => { await page.click(`[data-reader-part="${part}"] .cx-reader-block-tools button:text-is("Copy loaded body")`); await settle(); };
  const copyMatches = part => page.evaluate(part => window.qaCollapseCopied === window.readerFixture.currentParts()[part].text, part);
  await mkdir(artifactDir, { recursive: true });
  await page.reload();
  await page.click('text="English"');
  await page.evaluate(() => {
    document.documentElement.dataset.theme = 'light';
    Object.defineProperty(navigator, 'clipboard', { configurable: true, value: { writeText: async text => { window.qaCollapseCopied = text; } } });
  });

  await select('call_output_only');
  check('Call with only Output starts expanded', await expanded('output'));
  check('Only Output is rendered even before reading controls are used', await page.evaluate(() => document.querySelector('[data-reader-part="output"] .cx-reader-source').textContent.startsWith('Standalone Call output')));
  check('Source presentation is bounded without changing the saved body', await page.evaluate(() => document.querySelector('[data-reader-part="output"] .cx-reader-source').textContent.length === 100000 && window.readerFixture.currentParts().output.text.length > 100000));
  await copy('output');
  check('Copy includes the full loaded body with exact CRLF beyond the visual window', await copyMatches('output'));
  await toggle('output');
  check('Only Output can be manually collapsed', !await expanded('output'));
  await select('context');
  check('Ordinary message starts expanded', await expanded('input'));
  await select('call_output_only');
  check('Manual collapse survives switching entries', !await expanded('output'));
  await refresh();
  check('Manual collapse survives new event revision and changed output bytes', !await expanded('output') && await page.evaluate(() => window.readerFixture.currentParts().output.text.endsWith('Refreshed output 1')));
  await toggle('output');
  await copy('output');
  check('Copy after refresh includes all updated bytes', await copyMatches('output'));
  await refresh();
  check('Manual expansion survives realtime refresh', await expanded('output'));
  await page.evaluate(() => window.readerFixture.setDetailHidden(true));
  await settle();
  check('Manual expansion survives temporarily absent detail data', await expanded('output'));
  await page.evaluate(() => window.readerFixture.setDetailHidden(false));
  await settle();
  check('Restored detail preserves the expanded block', await expanded('output'));

  await select('command');
  check('Paired Call expands Input', await expanded('input'));
  check('Paired Call collapses Output', !await expanded('output'));
  await toggle('output');
  await toggle('input');
  await select('result_pair');
  check('Paired Result expands Output', await expanded('output'));
  check('Paired Result collapses Input', !await expanded('input'));
  await toggle('input');
  await toggle('output');
  await refresh();
  await select('command');
  check('Call manual Input and Output choices survive switching and refresh', !await expanded('input') && await expanded('output'));
  await select('result_pair');
  check('Result manual choices survive switching and refresh', await expanded('input') && !await expanded('output'));

  await select('call_empty_input');
  check('A loaded zero-byte Input does not collapse the sole Output', await expanded('output'));
  await select('result_input_placeholder');
  check('Result Output placeholder does not collapse the sole Input', await expanded('input'));
  check('Output not saved integrity notice remains visible', await page.evaluate(() => document.querySelector('[data-reader-part="output"] .cx-reader-integrity').textContent.includes('Output not saved')));

  await select('deferred_pair');
  check('Confirmed unloaded Input participates in paired Call defaults', await expanded('input') && !await expanded('output'));
  check('Confirmed Input is initially awaiting body data', await page.evaluate(() => !document.querySelector('[data-reader-part="input"] .cx-reader-source')));
  await page.evaluate(() => window.readerFixture.reveal());
  await settle();
  check('Arrival of confirmed body does not change either default', await expanded('input') && !await expanded('output') && await page.evaluate(() => document.querySelector('[data-reader-part="input"] .cx-reader-source').textContent.includes('Input confirmed by reference')));

  await select('unknown_empty_pair');
  check('Unknown-size Input is provisionally present before its response', await expanded('input') && !await expanded('output'));
  await page.evaluate(() => window.readerFixture.revealUnknown());
  await settle();
  check('Empty response resolves the sole Output to expanded', await expanded('output'));
  await refresh();
  await page.evaluate(() => window.readerFixture.setDetailHidden(true));
  await settle();
  check('Resolved sole Output does not refold when detail is temporarily absent', await expanded('output'));
  await page.evaluate(() => window.readerFixture.setDetailHidden(false));
  await settle();
  await select('context');
  await select('unknown_empty_pair');
  check('Resolved default stays stable across refresh, restoration and switching', await expanded('output'));
  await select('unknown_empty_manual');
  await toggle('output');
  await toggle('output');
  check('A user can explicitly collapse a provisionally folded Output', !await expanded('output'));
  await page.evaluate(() => window.readerFixture.revealUnknown());
  await settle();
  check('Resolving an empty counterpart preserves explicit Output collapse', !await expanded('output'));

  await select('error');
  check('Failure starts with Error before Input and Output', await page.evaluate(() => [...document.querySelectorAll('.cx-reader-block')].map(block => block.dataset.readerPart).join(',') === 'error,input,output'));
  check('Failure initially expands every available body', await expanded('error') && await expanded('input') && await expanded('output'));
  await toggle('error');
  await toggle('input');
  await select('context');
  await select('error');
  await refresh();
  check('Failure preserves manual collapse over its expand defaults', !await expanded('error') && !await expanded('input') && await expanded('output'));

  await select('partial');
  check('Partial Input starts expanded despite Output placeholder', await expanded('input'));
  await toggle('input');
  check('Collapsed partial body still exposes pagination', await page.evaluate(() => !!document.querySelector('[data-reader-part="input"] .cx-more-content')));
  await page.click('[data-reader-part="input"] .cx-more-content >> nth=0');
  await settle();
  check('Loading the next page preserves manual collapse and completes the data', !await expanded('input') && await page.evaluate(() => window.readerFixture.currentParts().input.nextCursor === null && !document.querySelector('[data-reader-part="input"] .cx-more-content')));
  await select('context');
  await select('partial');
  await refresh();
  check('Loaded body stays collapsed after switching and realtime refresh', !await expanded('input'));
  await page.fill('[aria-label="Search loaded entry body"]', 'easy to find');
  await settle();
  check('Search includes loaded text inside a collapsed block', await page.evaluate(() => document.querySelector('.cx-reader-search-results button')?.textContent.includes('easy to find')));
  await page.click('.cx-reader-search-results button');
  await settle();
  check('Search selection expands the block in source view and marks exact text', await expanded('input') && await page.evaluate(() => document.querySelector('[data-reader-hit]')?.textContent === 'easy to find' && [...document.querySelectorAll('[data-reader-part="input"] .cx-reader-block-tools button')].some(button => button.textContent === 'Body source' && button.getAttribute('aria-pressed') === 'true')));
  await copy('input');
  check('Copy after paging and search contains the entire loaded source', await copyMatches('input'));
  await page.click('[data-reader-part="input"] .cx-reader-block-tools button:text-is("Reading view")');
  await settle();
  check('Body source can still switch back to the JSON reading view', await page.evaluate(() => !!document.querySelector('[data-reader-part="input"] .cx-reader-json-tree')));
  await select('context');
  await select('partial');
  check('Search-expanded block and reader mode survive switching', await expanded('input') && await page.evaluate(() => !!document.querySelector('[data-reader-part="input"] .cx-reader-json-tree')));

  await select('error');
  await toggle('error');
  await toggle('input');
  await page.click('.cx-reader-expand');
  await page.evaluate(() => { document.querySelector('.cx-detail-body').scrollTop = 0; });
  await settle();
  await page.screenshot({ path: `${artifactDir}/failure-bodies.png` });
  await select('call_output_only');
  await page.click('.cx-reader-expand');
  await page.evaluate(() => { document.querySelector('.cx-detail-body').scrollTop = 0; });
  await settle();
  await page.screenshot({ path: `${artifactDir}/sole-call-output.png` });
  await writeFile(`${artifactDir}/checks.json`, JSON.stringify(checks, null, 2));
  return checks;
}
